export const PROVIDER_AWS = 'aws';
export const PROVIDER_GCP = 'gcp';
export const PROVIDER_AZURE = 'azure';
export const PROVIDER_CLOUDFLARE = 'cloudflare';
export const PROVIDER_DIGITALOCEAN = 'digitalocean';
export const PROVIDER_ORACLE = 'oracle';

export const DEFAULT_BASE_URL =
  'https://raw.githubusercontent.com/rezmoss/cloudip-db/main/data';
export const DEFAULT_DATA_URL = `${DEFAULT_BASE_URL}/cloudip.msgpack.gz`;
export const DEFAULT_VERSION_URL = `${DEFAULT_BASE_URL}/version.json`;

export const HOUR_MS = 60 * 60 * 1000;
export const DEFAULT_TTL_MS = 24 * HOUR_MS;

export async function loadEmbeddedGz(): Promise<Uint8Array | undefined> {
  if (typeof process === 'undefined' || !process.versions?.node) {
    return undefined;
  }
  const { readFile } = await import('node:fs/promises');
  const path = await import('node:path');
  const url = await import('node:url');
  let here: string;
  try {
    here = path.dirname(url.fileURLToPath(import.meta.url));
  } catch {
    here =
      typeof __dirname !== 'undefined' ? __dirname : process.cwd();
  }
  const candidates = [
    path.join(here, '..', 'data', 'cloudip.msgpack.gz'),
    path.join(here, 'data', 'cloudip.msgpack.gz'),
    path.join(process.cwd(), 'data', 'cloudip.msgpack.gz'),
  ];
  for (const p of candidates) {
    try {
      return new Uint8Array(await readFile(p));
    } catch {
      // try next
    }
  }
  return undefined;
}

import type { Range } from './types.js';

interface Node {
  zero?: Node;
  one?: Node;
  range?: Range;
}

export class CIDRTrie {
  private v4: Node = {};
  private v6: Node = {};

  insert(range: Range): void {
    const parsed = parseCIDR(range.cidr);
    if (!parsed) return;
    const root = parsed.bits.length === 32 ? this.v4 : this.v6;
    let node = root;
    for (let i = 0; i < parsed.prefix; i++) {
      const bit = parsed.bits[i] === 1 ? 'one' : 'zero';
      node[bit] ??= {};
      node = node[bit]!;
    }
    node.range ??= range;
  }

  lookup(ip: string): Range | undefined {
    const bits = ipToBits(ip);
    if (!bits) return undefined;
    const root = bits.length === 32 ? this.v4 : this.v6;
    let node: Node | undefined = root;
    let best = node.range;
    for (let i = 0; i < bits.length && node; i++) {
      node = bits[i] === 1 ? node.one : node.zero;
      if (node?.range) best = node.range;
    }
    return best;
  }
}

interface ParsedCIDR {
  bits: (0 | 1)[];
  prefix: number;
}

function parseCIDR(cidr: string): ParsedCIDR | null {
  const slash = cidr.indexOf('/');
  const ip = slash >= 0 ? cidr.slice(0, slash) : cidr;
  const bits = ipToBits(ip);
  if (!bits) return null;
  const prefix =
    slash >= 0 ? Number.parseInt(cidr.slice(slash + 1), 10) : bits.length;
  if (!Number.isFinite(prefix) || prefix < 0 || prefix > bits.length) {
    return null;
  }
  return { bits, prefix };
}

function ipToBits(ip: string): (0 | 1)[] | null {
  return ip.includes(':') ? ipv6ToBits(ip) : ipv4ToBits(ip);
}

function ipv4ToBits(ip: string): (0 | 1)[] | null {
  const parts = ip.split('.');
  if (parts.length !== 4) return null;
  const bits: (0 | 1)[] = [];
  for (const p of parts) {
    const n = Number.parseInt(p, 10);
    if (!Number.isFinite(n) || n < 0 || n > 255) return null;
    for (let i = 7; i >= 0; i--) bits.push(((n >> i) & 1) as 0 | 1);
  }
  return bits;
}

function ipv6ToBits(ip: string): (0 | 1)[] | null {
  const dbl = ip.split('::');
  if (dbl.length > 2) return null;
  const head = dbl[0] ? dbl[0].split(':') : [];
  const tail = dbl[1] ? dbl[1].split(':') : [];
  const missing = 8 - head.length - tail.length;
  if (missing < 0 && dbl.length === 2) return null;
  if (dbl.length === 1 && head.length !== 8) return null;
  const groups: string[] =
    dbl.length === 2
      ? [...head, ...Array(missing).fill('0'), ...tail]
      : head;
  if (groups.length !== 8) return null;
  const bits: (0 | 1)[] = [];
  for (const g of groups) {
    const n = Number.parseInt(g || '0', 16);
    if (!Number.isFinite(n) || n < 0 || n > 0xffff) return null;
    for (let i = 15; i >= 0; i--) bits.push(((n >> i) & 1) as 0 | 1);
  }
  return bits;
}

import type { VersionInfo } from './types.js';
import {
  DEFAULT_DATA_URL,
  DEFAULT_VERSION_URL,
} from './constants.js';
import { gunzip, sha256Hex } from './decode.js';

export interface FetchEnv {
  fetch: typeof fetch;
  dataURL: string;
  versionURL: string;
  signal?: AbortSignal;
}

export async function fetchVersion(env: Partial<FetchEnv> = {}): Promise<VersionInfo> {
  const doFetch = env.fetch ?? globalThis.fetch;
  const url = env.versionURL ?? DEFAULT_VERSION_URL;
  const res = await doFetch(url, { signal: env.signal });
  if (!res.ok) throw new Error(`js-cloudip: version.json HTTP ${res.status} from ${url}`);
  return (await res.json()) as VersionInfo;
}

export async function fetchData(
  env: Partial<FetchEnv> = {},
  verifyAgainst?: VersionInfo,
): Promise<{ bytes: Uint8Array; version: string }> {
  const doFetch = env.fetch ?? globalThis.fetch;
  const url = env.dataURL ?? DEFAULT_DATA_URL;
  const res = await doFetch(url, { signal: env.signal });
  if (!res.ok) throw new Error(`js-cloudip: data HTTP ${res.status} from ${url}`);
  const bytes = new Uint8Array(await res.arrayBuffer());
  const info = verifyAgainst ?? (await fetchVersion(env));
  const raw = await gunzip(bytes);
  const hash = await sha256Hex(raw);
  if (hash !== info.sha256) {
    throw new Error(
      `js-cloudip: sha256 mismatch (expected ${info.sha256}, got ${hash})`,
    );
  }
  return { bytes, version: info.version };
}

import { decode as msgpackDecode } from '@msgpack/msgpack';
import type { Database, Range } from './types.js';

interface RawRange {
  cidr: string;
  p: number;
  r?: string;
  s?: string;
}

interface RawDatabase {
  version: string;
  build_time: number;
  providers: string[];
  ranges: RawRange[];
}

export async function gunzip(buf: Uint8Array): Promise<Uint8Array> {
  if (typeof DecompressionStream !== 'undefined') {
    const ds = new DecompressionStream('gzip');
    const stream = new Blob([buf as BlobPart]).stream().pipeThrough(ds);
    const out = await new Response(stream).arrayBuffer();
    return new Uint8Array(out);
  }
  const { gunzipSync } = await import('node:zlib');
  return new Uint8Array(gunzipSync(buf));
}

export async function decodeDatabase(gzBuf: Uint8Array): Promise<Database> {
  const raw = await gunzip(gzBuf);
  const obj = msgpackDecode(raw) as RawDatabase;
  const providers = obj.providers;
  const ranges: Range[] = obj.ranges.map((r) => {
    const provider = providers[r.p];
    if (!provider) throw new Error(`js-cloudip: unknown provider index ${r.p}`);
    const out: Range = { cidr: r.cidr, provider };
    if (r.r) out.region = r.r;
    if (r.s) out.service = r.s;
    return out;
  });
  return {
    version: obj.version,
    build_time: obj.build_time,
    providers,
    ranges,
  };
}

export async function sha256Hex(buf: Uint8Array): Promise<string> {
  if (typeof crypto !== 'undefined' && crypto.subtle) {
    const ab = buf.buffer.slice(
      buf.byteOffset,
      buf.byteOffset + buf.byteLength,
    ) as ArrayBuffer;
    const digest = await crypto.subtle.digest('SHA-256', ab);
    return [...new Uint8Array(digest)]
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('');
  }
  const { createHash } = await import('node:crypto');
  return createHash('sha256').update(buf).digest('hex');
}

